[ -f pubspec.yaml ] || exit 1
mkdir -p 'android' 'android/app' 'android/app/src/main/kotlin/com/proqube/oraahora' 'android/app/src/main/res/drawable' 'android/app/src/main/res/mipmap-hdpi' 'android/app/src/main/res/mipmap-mdpi' 'android/app/src/main/res/mipmap-xhdpi' 'android/app/src/main/res/mipmap-xxhdpi' 'android/app/src/main/res/mipmap-xxxhdpi' 'android/app/src/main/res/values' 'android/gradle/wrapper' 'assets/data' 'assets/fonts' 'lib/models' 'lib/screens/gate_explainer' 'lib/screens/home' 'lib/screens/onboarding' 'lib/screens/paywall' 'lib/screens/prayer_detail' 'lib/services' 'lib/theme' 'lib/widgets' 'store_assets'

cat > 'android/app/build.gradle' <<'EOF_dc46f9f5'
plugins {
    id "com.android.application"
    id "kotlin-android"
    id "dev.flutter.flutter-gradle-plugin"
}

android {
    namespace "com.proqube.oraahora"
    compileSdk flutter.compileSdkVersion
    ndkVersion flutter.ndkVersion

    compileOptions {
        coreLibraryDesugaringEnabled true
        sourceCompatibility JavaVersion.VERSION_17
        targetCompatibility JavaVersion.VERSION_17
    }

    kotlinOptions {
        jvmTarget = JavaVersion.VERSION_17
    }

    defaultConfig {
        applicationId "com.proqube.oraahora"
        // flutter_local_notifications y device_apps funcionan desde API 21,
        // pero se fija 23 para simplificar el manejo de permisos en tiempo
        // de ejecucion (Android 6.0+) usados por el gate de accesibilidad.
        minSdk 23
        targetSdk flutter.targetSdkVersion
        versionCode flutter.versionCode
        versionName flutter.versionName
    }

    buildTypes {
        release {
            // TODO: antes de publicar, configurar una signingConfig de
            // release real (keystore propio) en vez de firmar con la
            // clave de debug.
            signingConfig signingConfigs.debug
        }
    }
}

flutter {
    source "../.."
}

dependencies {
    coreLibraryDesugaring "com.android.tools:desugar_jdk_libs:2.1.4"
    implementation "org.jetbrains.kotlin:kotlin-stdlib-jdk8:1.9.22"
}
EOF_dc46f9f5

cat > 'android/app/src/main/kotlin/com/proqube/oraahora/MainActivity.kt' <<'EOF_72a74b43'
package com.proqube.oraahora

import android.content.Context
import android.content.ComponentName
import android.content.Intent
import android.os.Bundle
import android.net.Uri
import android.os.Build
import android.os.PowerManager
import android.provider.Settings
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel

/**
 * Activity principal de Flutter. Ademas de arrancar el motor de Flutter,
 * expone un MethodChannel ("com.proqube.oraahora/gate") con operaciones
 * puntuales que si requieren codigo nativo:
 *  - abrir la pantalla de Ajustes > Accesibilidad de Android.
 *  - comprobar si PrayerGateAccessibilityService esta activo.
 *  - pedir (o comprobar) la exclusion de Ora Ahora de la optimizacion de
 *    bateria de Android, para que "Pausa y Ora" no sea silenciada por el
 *    sistema en fabricantes con gestion agresiva de bateria.
 *
 * El resto del estado de "Pausa y Ora" (apps bloqueadas, interruptor
 * general, minutos de gracia) se comparte con el servicio de accesibilidad
 * a traves de SharedPreferences (ver PrefsService.dart y
 * PrayerGateAccessibilityService.kt), sin necesidad de MethodChannel.
 */
class MainActivity : FlutterActivity() {
    private val channelName = "com.proqube.oraahora/gate"

    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)

        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, channelName)
            .setMethodCallHandler { call, result ->
                when (call.method) {
                    "openAccessibilitySettings" -> {
                        try {
                            val intent = Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)
                            intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                            // Pide a Ajustes que llegue con NUESTRO servicio
                            // resaltado (soportado en AOSP/Pixel/Samsung y la
                            // mayoria de OEM recientes; en el resto se ignora
                            // sin causar error), para que la persona no tenga
                            // que buscar "Ora Ahora" entre los menus.
                            val componente = ComponentName(
                                applicationContext,
                                PrayerGateAccessibilityService::class.java,
                            ).flattenToString()
                            val fragmentArgs = Bundle().apply {
                                putString(":settings:fragment_args_key", componente)
                            }
                            intent.putExtra(":settings:fragment_args_key", componente)
                            intent.putExtra(":settings:show_fragment_args", fragmentArgs)
                            startActivity(intent)
                            result.success(null)
                        } catch (e: Exception) {
                            result.error("OPEN_SETTINGS_FAILED", e.message, null)
                        }
                    }
                    "isAccessibilityServiceEnabled" -> {
                        result.success(PrayerGateAccessibilityService.isEnabled(applicationContext))
                    }
                    "isIgnoringBatteryOptimizations" -> {
                        try {
                            result.success(isIgnoringBatteryOptimizations())
                        } catch (e: Exception) {
                            result.error("BATTERY_OPT_CHECK_FAILED", e.message, null)
                        }
                    }
                    "requestIgnoreBatteryOptimizations" -> {
                        try {
                            if (!isIgnoringBatteryOptimizations()) {
                                val intent = Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS)
                                intent.data = Uri.parse("package:$packageName")
                                intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                                startActivity(intent)
                            }
                            result.success(null)
                        } catch (e: Exception) {
                            result.error("BATTERY_OPT_REQUEST_FAILED", e.message, null)
                        }
                    }
                    else -> result.notImplemented()
                }
            }
    }

    private fun isIgnoringBatteryOptimizations(): Boolean {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M) return true
        val powerManager = getSystemService(Context.POWER_SERVICE) as PowerManager
        return powerManager.isIgnoringBatteryOptimizations(packageName)
    }
}
EOF_72a74b43

cat > 'android/app/src/main/kotlin/com/proqube/oraahora/PrayerGateForegroundService.kt' <<'EOF_6743eb03'
package com.proqube.oraahora

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.app.Service
import android.content.Context
import android.content.Intent
import android.os.Build
import android.os.IBinder

/**
 * Servicio en primer plano (foreground service) cuya unica funcion es
 * darle al sistema operativo una señal adicional de "esta app sigue
 * activa", para que [PrayerGateAccessibilityService] tenga menos
 * probabilidad de ser detenido en segundo plano por la gestion agresiva
 * de bateria de algunos fabricantes (Xiaomi, Samsung, Huawei, etc.), que
 * a veces matan servicios de Accesibilidad silenciosamente.
 *
 * Muestra una notificacion PERSISTENTE, silenciosa y de baja prioridad
 * (`IMPORTANCE_MIN`, sin sonido ni vibracion) que le explica al usuario,
 * en español, por que sigue viendo el icono de Ora Ahora en la barra de
 * estado: "Ora Ahora está activo para interceptar aperturas de apps". El
 * usuario puede detener este servicio en cualquier momento desactivando
 * "Pausa y Ora" desde Ajustes (ver `GateService.setGateEnabled`) o
 * revocando el permiso de Accesibilidad.
 *
 * Este servicio NO hace ningun trabajo de deteccion por si mismo:
 * [PrayerGateAccessibilityService] sigue siendo el unico responsable de
 * detectar aperturas de apps y lanzar la pausa de oracion. Este servicio
 * solo mantiene la señal de "primer plano" ante Android.
 */
class PrayerGateForegroundService : Service() {

    companion object {
        private const val CHANNEL_ID = "ora_ahora_gate_active"
        private const val NOTIFICATION_ID = 4201

        /** Inicia el servicio (llamado desde PrayerGateAccessibilityService). */
        fun start(context: Context) {
            val intent = Intent(context, PrayerGateForegroundService::class.java)
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                context.startForegroundService(intent)
            } else {
                context.startService(intent)
            }
        }

        /** Detiene el servicio (llamado cuando se desactiva Accesibilidad). */
        fun stop(context: Context) {
            context.stopService(Intent(context, PrayerGateForegroundService::class.java))
        }
    }

    override fun onBind(intent: Intent?): IBinder? = null

    override fun onCreate() {
        super.onCreate()
        createChannelIfNeeded()
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        startForeground(NOTIFICATION_ID, buildNotification())
        return START_STICKY
    }

    private fun createChannelIfNeeded() {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return
        val manager = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        if (manager.getNotificationChannel(CHANNEL_ID) != null) return
        val channel = NotificationChannel(
            CHANNEL_ID,
            "Pausa y Ora activa",
            NotificationManager.IMPORTANCE_MIN,
        )
        channel.description =
            "Notificación silenciosa que indica que la Pausa y Ora antes de abrir apps está activa."
        channel.setShowBadge(false)
        manager.createNotificationChannel(channel)
    }

    private fun buildNotification(): Notification {
        val openAppIntent = packageManager.getLaunchIntentForPackage(packageName)
        val contentIntent = if (openAppIntent != null) {
            PendingIntent.getActivity(
                this,
                0,
                openAppIntent,
                PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT,
            )
        } else {
            null
        }

        val builder = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            Notification.Builder(this, CHANNEL_ID)
        } else {
            @Suppress("DEPRECATION")
            Notification.Builder(this)
        }

        builder
            .setContentTitle("Ora Ahora")
            .setContentText("Ora Ahora está activo para interceptar aperturas de apps")
            .setSmallIcon(R.mipmap.ic_launcher)
            .setOngoing(true)
            .setCategory(Notification.CATEGORY_SERVICE)

        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
            @Suppress("DEPRECATION")
            builder.setPriority(Notification.PRIORITY_MIN)
        }

        if (contentIntent != null) {
            builder.setContentIntent(contentIntent)
        }

        return builder.build()
    }
}
EOF_6743eb03

