cat > 'android/app/src/main/res/values/colors.xml' <<'EOF_2eb8317c'
<?xml version="1.0" encoding="utf-8"?>
<resources>
    <!-- Debe coincidir con la paleta "Santuario" del lado Flutter
         (AppColors), para que PrayerGateActivity (pantalla 100% nativa)
         se vea consistente con el resto de la app:
         gate_background = AppColors.tealDeep  (verde abeto profundo)
         gate_accent     = dorado suave (legible sobre el fondo oscuro)
         gate_text_soft  = AppColors.tealLight (niebla de salvia) -->
    <color name="gate_background">#16342B</color>
    <color name="gate_accent">#D9B37C</color>
    <color name="gate_text">#F7F3EA</color>
    <color name="gate_text_soft">#DCE8DE</color>

    <!-- Fondo de arranque (ver drawable/launch_background.xml y
         styles.xml): mismo papel marfil que AppColors.cream. -->
    <color name="launch_background_color">#F7F3EA</color>
</resources>
EOF_2eb8317c

cat > 'android/app/src/main/res/values/styles.xml' <<'EOF_c82b7bcf'
<?xml version="1.0" encoding="utf-8"?>
<resources>
    <!-- Tema mostrado como splash mientras Android infla la primera
         Activity de Flutter (MainActivity). -->
    <style name="LaunchTheme" parent="@android:style/Theme.Black.NoTitleBar">
        <item name="android:windowBackground">@drawable/launch_background</item>
    </style>

    <!-- Tema usado por MainActivity una vez que Flutter ya se dibujó. -->
    <style name="NormalTheme" parent="@android:style/Theme.Black.NoTitleBar">
        <item name="android:windowBackground">@color/launch_background_color</item>
    </style>

    <!-- Tema para PrayerGateActivity: pantalla completa, sin action bar,
         para que la pausa de oración se sienta como un momento aparte. -->
    <style name="PrayerGateTheme" parent="@android:style/Theme.Black.NoTitleBar.Fullscreen">
        <item name="android:windowBackground">@color/gate_background</item>
        <item name="android:windowIsTranslucent">false</item>
    </style>

    <!-- Boton de opcion de animo en el check-in de PrayerGateActivity:
         mismo acento que el boton "Continuar", pero mas bajo/compacto ya
         que hay 6 en pantalla y deben verse como opciones equivalentes,
         no como una llamada a la accion unica. -->
    <style name="GateMoodButton" parent="@android:style/Widget.Button">
        <item name="android:layout_width">match_parent</item>
        <item name="android:layout_height">48dp</item>
        <item name="android:layout_marginBottom">10dp</item>
        <item name="android:textAllCaps">false</item>
        <item name="android:textSize">15sp</item>
        <item name="android:backgroundTint">@color/gate_accent</item>
        <item name="android:textColor">@color/gate_text</item>
    </style>
</resources>
EOF_c82b7bcf

